INSERT INTO "IMPORT OPEX" ("Cost Center", "Account", "Years", "Months", v, ver, is_deleted) SELECT coalesce(k0."Cost Center", throwIf(isNull(k0."Cost Center"), 'cells name a member Cost Center does not have')), coalesce(k1."Account", throwIf(isNull(k1."Account"), 'cells name a member Account does not have')), coalesce(k2."Years", throwIf(isNull(k2."Years"), 'cells name a member Years does not have')), coalesce(k3."Months", throwIf(isNull(k3."Months"), 'cells name a member Months does not have')), sum(toFloat64(c.value)), toUnixTimestamp64Micro(now64(6)), 0
FROM file('cells/IMPORT OPEX.csv', 'CSVWithNames', '"Cost Center" String, "Account" String, "Years" String, "Months" String, "value" String') c LEFT JOIN "dim Cost Center" k0 ON k0.name = c."Cost Center" LEFT JOIN "dim Account" k1 ON k1.name = c."Account" LEFT JOIN "dim Years" k2 ON k2.name = c."Years" LEFT JOIN "dim Months" k3 ON k3.name = c."Months"
GROUP BY ALL;
